//! The C# of a page: the view model its bindings compile against, and its code-behind. Neither is
//! read back, since the XAML holds every path and action. No document text reaches them: the names
//! are Weft names, C# identifiers once a keyword takes its `_` (`data::member`), and action names
//! match `[a-z][A-Za-z0-9.]*`, so they need no escape inside a string literal.

use std::fmt::Write;

use crate::Unsupported;
use crate::data::{Data, Leaf, Ty, member};
use crate::xaml::type_name;

const HEADER: &str =
    "// Generated by Weft: generating the page again overwrites any edit.\n#nullable enable\n";

/// `todo.add` → `todo_addCommand`: action names hold no `_` (SPEC §2.2), so the name maps back.
pub fn command(action: &str) -> String {
    format!("{}Command", action.replace('.', "_"))
}

pub fn code_behind(name: &str, namespace: &str) -> String {
    format!(
        "{HEADER}using Microsoft.UI.Xaml.Controls;\n\nnamespace {namespace};\n\n\
         public sealed partial class {name}Page : Page\n{{\n    \
         public {name}ViewModel ViewModel {{ get; }} = new();\n\n    \
         public {name}Page()\n    {{\n        InitializeComponent();\n    }}\n}}\n"
    )
}

/// A generated class: the view model (shape 0), an object, or the item of a list.
struct Class {
    shape: usize,
    name: String,
    item: bool,
    /// The class of the nearest enclosing list item, which an item's `WeftParent` holds.
    parent: Option<String>,
}

/// `<Name>ViewModel.cs`. Class names come from the path in PascalCase (`$.todos` items are
/// `<Name>TodosItem`, `$.user` is `<Name>UserData`), so two paths can ask for one name; that, and a
/// member named like its class, is refused, because C# rejects both.
pub fn view_model(
    data: &Data,
    name: &str,
    namespace: &str,
    actions: &[String],
) -> Result<String, Vec<Unsupported>> {
    let root = format!("{name}ViewModel");
    let mut classes = vec![Class {
        shape: 0,
        name: root.clone(),
        item: false,
        parent: None,
    }];
    collect(data, 0, name, None, &mut classes);
    let mut problems = vec![];
    for (i, c) in classes.iter().enumerate() {
        let path = &data.shapes[c.shape].path;
        if let Some(other) = classes[..i].iter().find(|o| o.name == c.name) {
            let first = &data.shapes[other.shape].path;
            let message = format!("`{first}` and `{path}` both need the C# class `{}`", c.name);
            problems.push(Unsupported::new(path.clone(), message));
        }
        if let Some(&member) = data.shapes[c.shape].fields.get(&c.name) {
            problems.push(Unsupported::new(
                data.shapes[member].path.clone(),
                format!("`{}` is the name of its generated class", c.name),
            ));
        }
    }
    if !problems.is_empty() {
        return Err(problems);
    }
    let mut out = format!(
        "{HEADER}using System;\nusing System.Collections.ObjectModel;\nusing System.ComponentModel;\n\
         using System.Runtime.CompilerServices;\nusing System.Windows.Input;\n\nnamespace {namespace};\n"
    );
    for c in &classes {
        let commands = if c.shape == 0 { actions } else { &[] };
        class(&mut out, data, &classes, c, &root, commands);
    }
    Ok(out)
}

/// `$.cart.items` → `<Name>CartItems`: the members of the path in PascalCase, without indexes.
/// An object's class adds `Data` and a list item's `Item`.
pub fn class_base(name: &str, path: &str) -> String {
    let members = path
        .split('.')
        .skip(1)
        .filter(|s| !s.starts_with(|c: char| c.is_ascii_digit()));
    format!("{name}{}", members.map(type_name).collect::<String>())
}

fn collect(data: &Data, shape: usize, name: &str, parent: Option<&str>, out: &mut Vec<Class>) {
    for &child in data.shapes[shape].fields.values() {
        let base = class_base(name, &data.shapes[child].path);
        let (at, name_of, item) = match data.ty(child) {
            Ty::Object => (child, format!("{base}Data"), false),
            Ty::Array(item) if data.ty(item) == Ty::Object => (item, format!("{base}Item"), true),
            _ => continue,
        };
        let inner = if item {
            Some(name_of.clone())
        } else {
            parent.map(str::to_owned)
        };
        let parent = parent.map(str::to_owned);
        out.push(Class {
            shape: at,
            name: name_of,
            item,
            parent,
        });
        collect(data, at, name, inner.as_deref(), out);
    }
}

fn type_of(data: &Data, classes: &[Class], shape: usize) -> String {
    match data.ty(shape) {
        Ty::Leaf(Leaf::Text) => "string".to_owned(),
        Ty::Leaf(Leaf::Flag) => "bool".to_owned(),
        Ty::Leaf(Leaf::Number) => "double".to_owned(),
        Ty::Array(item) => format!("ObservableCollection<{}>", type_of(data, classes, item)),
        Ty::Object => classes
            .iter()
            .find(|c| c.shape == shape)
            .map(|c| c.name.clone())
            .unwrap_or_default(),
    }
}

/// The lists an owner keeps placed: its own, and those of its objects, which have no owner of
/// their own among the list items. Each is the C# access and the Weft path below the owner.
fn lists(data: &Data, shape: usize, access: &str, path: &str, out: &mut Vec<(String, String)>) {
    for (field, &child) in &data.shapes[shape].fields {
        let access = format!("{access}{}", member(field));
        let path = format!("{path}.{field}");
        match data.ty(child) {
            // A list of text or flags holds nothing to place.
            Ty::Array(item) if data.ty(item) == Ty::Object => out.push((access, path)),
            Ty::Object => lists(data, child, &format!("{access}."), &path, out),
            _ => {}
        }
    }
}

fn class(
    out: &mut String,
    data: &Data,
    classes: &[Class],
    c: &Class,
    root: &str,
    actions: &[String],
) {
    let vm = c.shape == 0;
    let mut placed = vec![];
    if vm || c.item {
        lists(data, c.shape, "", "", &mut placed);
    }
    let w = &mut *out;
    let item = if c.item { ", IWeftItem" } else { "" };
    let _ = write!(
        w,
        "\npublic sealed partial class {} : INotifyPropertyChanged{item}\n{{\n    \
         public event PropertyChangedEventHandler? PropertyChanged;\n",
        c.name
    );
    if vm {
        w.push_str("    public event EventHandler<WeftEvent>? Performed;\n");
    }
    if c.item {
        let parent = c.parent.as_deref().unwrap_or("object");
        let _ = write!(
            w,
            "\n    public {root}? WeftRoot {{ get; private set; }}\n    \
             public {parent}? WeftParent {{ get; private set; }}\n    \
             public string WeftPath {{ get; private set; }} = \"\";\n"
        );
    }
    if !actions.is_empty() || !placed.is_empty() {
        let _ = write!(w, "\n    public {}()\n    {{\n", c.name);
        for action in actions {
            let field = command(action);
            let _ = writeln!(
                w,
                "        {field} = new WeftCommand(\"{action}\", Perform);"
            );
        }
        for (list, _) in &placed {
            let _ = writeln!(
                w,
                "        {list}.CollectionChanged += (_, _) => WeftPlaceLists();"
            );
        }
        w.push_str("    }\n");
    }
    for (name, &child) in &data.shapes[c.shape].fields {
        let field = member(name);
        let ty = type_of(data, classes, child);
        let _ = match data.ty(child) {
            Ty::Leaf(leaf) => write!(
                w,
                "\n    public {ty} {field}\n    {{\n        get => Weft_{field};\n        \
                 set => WeftSet(ref Weft_{field}, value);\n    }}\n    \
                 private {ty} Weft_{field} = {};\n",
                match leaf {
                    Leaf::Text => "\"\"",
                    Leaf::Flag => "false",
                    Leaf::Number => "0",
                }
            ),
            _ => write!(w, "\n    public {ty} {field} {{ get; }} = new();\n"),
        };
    }
    if !actions.is_empty() {
        w.push('\n');
    }
    for action in actions {
        let _ = writeln!(w, "    public ICommand {} {{ get; }}", command(action));
    }
    if vm {
        w.push_str(
            "\n    /// <summary>Hands an action to the host (SPEC §2.2): <c>OnPerformed</c>, then <c>Performed</c>.</summary>\n    \
             public void Perform(string action, string? id = null, string? item = null)\n    {\n        \
             var e = new WeftEvent(action, id, item);\n        OnPerformed(e);\n        \
             Performed?.Invoke(this, e);\n    }\n\n    partial void OnPerformed(WeftEvent e);\n",
        );
    }
    if c.item {
        let parent = c.parent.as_deref().unwrap_or("object");
        let _ = write!(
            w,
            "\n    void IWeftItem.WeftPlace(object root, object? parent, string path)\n    {{\n        \
             WeftRoot = ({root})root;\n        WeftParent = ({parent}?)parent;\n        \
             WeftPath = path;\n        WeftPlaceLists();\n    }}\n"
        );
    }
    if !placed.is_empty() || c.item {
        w.push_str("\n    private void WeftPlaceLists()\n    {\n");
        // A list item is placed by its own list; until then its lists have no path to give.
        let (owner, base) = if vm {
            ("this, null", "\"$")
        } else {
            w.push_str("        if (WeftRoot is null) return;\n");
            ("WeftRoot, this", "WeftPath + \"")
        };
        for (access, path) in &placed {
            let _ = writeln!(w, "        Weft.Place({access}, {owner}, {base}{path}\");");
        }
        w.push_str("    }\n");
    }
    w.push_str(
        "\n    private void WeftSet<T>(ref T store, T value, [CallerMemberName] string name = \"\")\n    {\n        \
         if (Equals(store, value)) return;\n        store = value;\n        \
         PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));\n    }\n}\n",
    );
}
